CREATE TABLE IF NOT EXISTS `voiceCloneApplyLogs` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`voiceCloneId` int NOT NULL,
	`cloneName` varchar(255) NOT NULL,
	`projectId` int NOT NULL,
	`projectTitle` varchar(500) NOT NULL,
	`avatarCount` int NOT NULL DEFAULT 1,
	`avatarNames` text,
	`applyMode` enum('all','selected') NOT NULL DEFAULT 'all',
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `voiceCloneApplyLogs_id` PRIMARY KEY(`id`)
);

ALTER TABLE `userAvatars` ADD COLUMN IF NOT EXISTS `defaultTtsVoiceId` varchar(100);
ALTER TABLE `userAvatars` ADD COLUMN IF NOT EXISTS `defaultVoiceCloneId` int;
ALTER TABLE `userAvatars` ADD COLUMN IF NOT EXISTS `defaultRole` enum('instructor','host','guest','narrator') DEFAULT 'instructor';

